INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(51311, 'Ezekiel 42:15', 'Ezekiel', 42, 15, 'کله چې هغه سړي د عبادتځای دننه اندازه کول سرته ورسول، هغه زه د ختیځې دروازې په لاره دباندې بوتلم او بیا یې شاوخوا ټول ځای اندازه کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel42_verse_15.mp3', '', 1761754199, 1761754199),
(51312, 'Ezekiel 42:16', 'Ezekiel', 42, 16, 'هغه د اندازه کولو لرګی واخیست او ختیځه خوا یې اندازه کړه او هغه دوه سوه او پنځوس متره وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel42_verse_16.mp3', '', 1761754199, 1761754199),
(51313, 'Ezekiel 42:17', 'Ezekiel', 42, 17, 'بیا هغه شمالي خوا اندازه کړه او هغه دوه سوه او پنځوس متره وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel42_verse_17.mp3', '', 1761754199, 1761754199),
(51314, 'Ezekiel 42:18', 'Ezekiel', 42, 18, 'هغه جنوبي خوا اندازه کړه او هغه دوه سوه او پنځوس متره وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel42_verse_18.mp3', '', 1761754199, 1761754199),
(51315, 'Ezekiel 42:19', 'Ezekiel', 42, 19, 'په پای کې هغه لوېدیځې خوا ته تاو شو او هغه یې اندازه کړه او هغه هم دوه سوه او پنځوس متره وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel42_verse_19.mp3', '', 1761754199, 1761754199),
(51316, 'Ezekiel 42:20', 'Ezekiel', 42, 20, 'نو هغه د څلورو خواوو دېوال اندازه کړ. ګردچاپېره دېوال مربع شکله ؤ او څلور واړه خواو کې هغه دوه سوه او پنځوس متره ؤ. دا دېوال د دې دپاره ؤ چې سپېڅلی ځای د عادي ځای نه بېل کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel42_verse_20.mp3', '', 1761754199, 1761754199),
(51317, 'Esther 8:1', 'Esther', 8, 1, 'په هماغه ورځ خشایار پاچا د یهودیانو د دښمن یعنې هامان ټوله شتمني او جایداد ملکې استر ته ورکړ. استر پاچا ته وویل چې مردخای د هغې خپلوان دی. وروسته له دې مردخای ته اجازه وه چې د پاچا حضور ته ورشي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther8_verse_1.mp3', '', 1761754199, 1761754199),
(51318, 'Esther 8:2', 'Esther', 8, 2, 'پاچا خپله د مهر ګوته چې د هامان څخه یې بېرته اخیستې وه، راوویستله او مردخای ته یې ورکړه. بیا استر مردخای د هامان د شتمنۍ او جایداد مسوول وټاکه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther8_verse_2.mp3', '', 1761754199, 1761754199),
(51319, 'Esther 8:3', 'Esther', 8, 3, 'استر یوځل بیا د پاچا سره خبرې وکړې، د هغه پښو ته پرېوتله او ویې ژړل. استر هغه ته زاري وکړه چې د اجاجي هامان ناوړه پلان چې د یهودیانو په خلاف یې سنجولی ؤ، شنډ کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther8_verse_3.mp3', '', 1761754199, 1761754199),
(51320, 'Esther 8:4', 'Esther', 8, 4, 'نو کله چې پاچا خپله د سرو زرو امسا د استر خواته وراوږده کړه، هغه راپاڅېدله او د پاچا په مخکې ودرېدله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther8_verse_4.mp3', '', 1761754199, 1761754199),
(51321, 'Esther 8:5', 'Esther', 8, 5, 'هغې وویل: «که ستاسو اعلیحضرت خوښه وي او زما خیال او پروا ساتئ او زما سره مینه لرئ، نو مهرباني وکړئ یو فرمان خپور کړئ چې د حجاجي د همداتا د زوی هامان د هغو حکمونو د عملي کولو څخه دې مخنیوی وشي چې په ټوله امپراتورۍ کې یې د یهودیانو د له منځه وړلو دپاره ورکړي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther8_verse_5.mp3', '', 1761754199, 1761754199),
(51322, 'Esther 8:6', 'Esther', 8, 6, 'ځکه زه هغه مصیبت او بلا څنګه زغملای شم چې زما قوم او خپلوان زما په مخکې ووژل شي؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther8_verse_6.mp3', '', 1761754199, 1761754199),
(51323, 'Esther 8:7', 'Esther', 8, 7, 'نو بیا خشایار پاچا استر ملکې او یهودي مردخای ته وویل: «ګورئ، ما هامان په دې خاطر په دار وځړاوه چې د یهودیانو په خلاف یې دسیسه جوړه کړې وه او د هغه شتمني او جایداد مې استر ته ورکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther8_verse_7.mp3', '', 1761754199, 1761754199),
(51324, 'Esther 8:8', 'Esther', 8, 8, 'اوس تاسو کولای شئ چې په خپله خوښه یو بل فرمان د یهودیانو په خاطر د پاچا په نوم ولیکئ او د پاچا مهر ورباندې ولګوئ. ځکه هغه فرمان چې د پاچا په نوم لیکل شوی وي او د هغه مهر ورباندې لګېدلی وي هغه لغوه کېدای نه شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther8_verse_8.mp3', '', 1761754199, 1761754199),
(51325, 'Esther 8:9', 'Esther', 8, 9, 'نو بیا مردخای د درېمې میاشتې په درویشتمه ورځ چې د سیوان میاشت وه، د پاچا منشیان راوغوښتل او یهودیانو، د پاچا له خوا ټاکل شویو والیانو، د بېلابېلو ولایتونو نورو والیانو او مامورینو او د هند نه تر ایتوپیا پورې د یوسلو اووه ویشتو ولایتونو چارواکو ته یې لیکونه ولیکل. هر ولایت ته یې د هغوی د خط او هر قوم ته د هغوی د ژبې سره سم او یهودیانو ته یې هم د هغوی د خط او ژبې سره سم لیکونه ولیکل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther8_verse_9.mp3', '', 1761754199, 1761754199),
(51326, 'Esther 8:10', 'Esther', 8, 10, 'مردخای د خشایار پاچا په نوم لیکونه ولیکل او شاهي مهر یې ورباندې ولګاوه. لیکونه یې هغو اس سوارانو ته چې د پاچا په تېزو اسونو باندې سپاره وو، وسپارل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther8_verse_10.mp3', '', 1761754199, 1761754199),
(51327, 'Esther 8:11', 'Esther', 8, 11, 'د دې فرمان سره سم د پاچا له خوا یهودیانو دا اجازه درلودله چې په هر ښار کې د خپلې دفاع دپاره یوځای شي. که چېرې وسله وال کسان چې د هر قوم یا هر ولایت څخه وي او په یهودیانو، د هغوی په ښځو او د هغوی په ماشومانو حمله وکړي، هغوی حق لري چې خپل دښمنان ووژني او تباه یې کړي او مالونه یې لوټ کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther8_verse_11.mp3', '', 1761754199, 1761754199),
(51328, 'Esther 8:12', 'Esther', 8, 12, 'هغه ورځ چې د یهودیانو د ټول وژنې په خاطر د خشایار پاچا په ټولو ولایتونو کې ټاکل شوې وه، هغه د دولسمې میاشتې یعنې د اذر د میاشتې دیارلسمه ورځ وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther8_verse_12.mp3', '', 1761754199, 1761754199),
(51329, 'Esther 8:13', 'Esther', 8, 13, 'د فرمان متن باید د قانون په توګه هر ولایت ته صادر شي او د هر قوم خلکو ته دې په ډاګه شي، ترڅو یهودیان په هغې ورځې د خپلو دښمنانو نه د بدل اخیستلو دپاره تیار اوسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther8_verse_13.mp3', '', 1761754199, 1761754199),
(51330, 'Esther 8:14', 'Esther', 8, 14, 'قاصدان د پاچا په امر په شاهي اسونو باندې سپاره شول او په ډېرې بیړې سره روان شول. دا فرمان د شوش په بالاحصار کې هم خپور شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther8_verse_14.mp3', '', 1761754199, 1761754199),
(51331, 'Esther 8:15', 'Esther', 8, 15, 'مردخای چې شاهانه ابي او سپین رنګه کالي یې اغوستي وو، د سرو زرو لوی تاج یې په سر ؤ او د ښه کتان بانجاني چپنه یې اغوستې وه، د پاچا د حضور څخه لاړ. د شوش د ښار خلکو د خوشحالۍ چیغې وهلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther8_verse_15.mp3', '', 1761754199, 1761754199),
(51332, 'Esther 8:16', 'Esther', 8, 16, 'د یهودیانو دپاره دا د خوشحالۍ او ارامۍ وخت ؤ او نورو خلکو د هغوی عزت کاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther8_verse_16.mp3', '', 1761754199, 1761754199),
(51333, 'Esther 8:17', 'Esther', 8, 17, 'هر ولایت، هر ښار او هر ځای ته به چې د پاچا فرمان ورسېده، هلته به د یهودیانو په منځ کې خوښي او خوشحالي وه، مېلې به یې کولې او جشنونه به یې نیول. د نورو قومونو ډېرو خلکو خپل ځانونه یهودیان اعلان کړل، ځکه چې هغوی د یهودیانو څخه وېرېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther8_verse_17.mp3', '', 1761754199, 1761754199),
(51334, 'Psalms 84:1', 'Psalms', 84, 1, 'ای مطلق قادر څښتنه څومره زړه وړونکی دی ستا د اوسېدلو ځای', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms84_verse_1.mp3', '', 1761754199, 1761754199),
(51335, 'Psalms 84:2', 'Psalms', 84, 2, 'څومره مې زړه غواړي چې واوسم هلته څښتن دربار کې اوسېدو پسې مې چوي زړګی زه ژوندي خدای ته په خپل ټول زړه او ځان چیغې د خوښۍ وهمه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms84_verse_2.mp3', '', 1761754199, 1761754199),
(51336, 'Psalms 84:3', 'Psalms', 84, 3, 'د قربانۍ د ځایونو په خوا کې دې چڼچڼو، توتکیو ځالې جوړې کړې ځان ته او توتکۍ په کې بچي ساتي خپل مطلق قادر څښتنه، زما پاچا او زما خدایه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms84_verse_3.mp3', '', 1761754199, 1761754199),
(51337, 'Psalms 84:4', 'Psalms', 84, 4, 'هغوی څومره بختور دي چې اوسیږي ستا په کور کې او تل سندرې د ثنا ستا وایي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms84_verse_4.mp3', '', 1761754199, 1761754199),
(51338, 'Psalms 84:5', 'Psalms', 84, 5, 'هغوی څومره بختور دي چې د ستا نه قوت مومي څوک لري دا شوق چې د صهیون غره ته سفر وکړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms84_verse_5.mp3', '', 1761754199, 1761754199),
(51339, 'Psalms 84:6', 'Psalms', 84, 6, 'د بکا د وچې درې څخه چې دوی تېریږي نو له هغه ځای څخه چینې جوړیږي باران د مني ډکوي یې برکتونو باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms84_verse_6.mp3', '', 1761754199, 1761754199),
(51340, 'Psalms 84:7', 'Psalms', 84, 7, 'د دوی طاقت سفر کولو سره لا زیاتیږي او د دوی هر یو په صهیون کې حاضریږي خدای ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms84_verse_7.mp3', '', 1761754199, 1761754199),
(51341, 'Psalms 84:8', 'Psalms', 84, 8, 'ای څښتنه ای مطلق قادره خدایه، واوره دعا زما! ای د یعقوب خدایه، ته ماته غوږ ونیسه!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms84_verse_8.mp3', '', 1761754199, 1761754199),
(51342, 'Psalms 84:9', 'Psalms', 84, 9, 'ای خدایه، زمونږ پاچا ته چې مو سپر دی برکت ورکړه هغه پاچا چې تا په خپله غوره کړی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms84_verse_9.mp3', '', 1761754199, 1761754199),
(51343, 'Psalms 84:10', 'Psalms', 84, 10, 'د یوې ورځې تېرول ستا دربار کې بهتر دي بل ځای کې له زرو ورځو تش درېدل د خپل خدای کور د دروازې مخې ته د بدکارانو په خېمو کې اوسېدو څخه بهتر ګڼمه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms84_verse_10.mp3', '', 1761754199, 1761754199),
(51344, 'Psalms 84:11', 'Psalms', 84, 11, 'څښتن سپر دی زمونږ او ځلیږي لکه د لمر په شان هغه برکت راکوي مونږ ته په فضل او عزت نه سپموي هېڅ ښه شی له هغو څخه د چا چې لارې وي بې‌داغه لارې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms84_verse_11.mp3', '', 1761754199, 1761754199),
(51345, 'Psalms 84:12', 'Psalms', 84, 12, 'ای مطلق قادر څښتنه څومره بختور دی هغه کس چې په تا باندې توکل کوي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms84_verse_12.mp3', '', 1761754199, 1761754199),
(51346, 'Exodus 6:1', 'Exodus', 6, 1, 'څښتن موسی ته وویل: «اوس به ته وګورې چې زه د فرعون سره څه کوم. زه به هغه دومره مجبور کړم چې زما قوم پرېږدي چې لاړ شي او هغوی به په زوره د خپلې خاورې څخه وباسي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus6_verse_1.mp3', '', 1761754199, 1761754199),
(51347, 'Exodus 6:2', 'Exodus', 6, 2, 'خدای د موسی سره خبرې وکړې او ویې ویل: «زه څښتن یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus6_verse_2.mp3', '', 1761754199, 1761754199),
(51348, 'Exodus 6:3', 'Exodus', 6, 3, 'کله چې زه ابراهیم، اسحاق او یعقوب ته ورښکاره شوم، نو زه د مطلق قادر خدای په توګه راغلم، خو ما هغوی ته داسې ځان ور ونه پېژانده چې زما نوم څښتن دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus6_verse_3.mp3', '', 1761754199, 1761754199),
(51349, 'Exodus 6:4', 'Exodus', 6, 4, 'ما د هغوی سره دا لوظ هم وکړ چې زه به د کنعان ځمکه چې هغوی په کې د پردیو خلکو په توګه اوسېدل، دوی ته ورکوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus6_verse_4.mp3', '', 1761754199, 1761754199),
(51350, 'Exodus 6:5', 'Exodus', 6, 5, 'اوس ما د اسراییلیانو فریاد چې د مصریانو غلامان دي اورېدلی دی او ماته خپل لوظ په یاد دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus6_verse_5.mp3', '', 1761754199, 1761754199),
(51351, 'Exodus 6:6', 'Exodus', 6, 6, 'اسراییلیانو ته ووایه چې زه هغوی ته وایم: زه څښتن یم! زه به تاسو وژغورم او په خپل قدرتمند لاس سره به مصریانو ته سزا ورکړم او د غلامۍ څخه به مو ازاد کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus6_verse_6.mp3', '', 1761754199, 1761754199),
(51352, 'Exodus 6:7', 'Exodus', 6, 7, 'زه به ستاسو څخه خپل قوم جوړ کړم او ستاسو خدای به یم. کله چې زه تاسو د مصریانو د غلامۍ څخه ازاد کړم، بیا به پوه شئ چې زه ستاسو څښتن خدای یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus6_verse_7.mp3', '', 1761754199, 1761754199),
(51353, 'Exodus 6:8', 'Exodus', 6, 8, 'زه به تاسو هغه وطن ته راولم چې د هغه د ورکولو قسم مې د ابراهیم، اسحاق او یعقوب سره کړی ؤ. زه به دا وطن تاسو ته درکړم چې ستاسو شي. زه څښتن یم!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus6_verse_8.mp3', '', 1761754199, 1761754199),
(51354, 'Exodus 6:9', 'Exodus', 6, 9, 'موسی اسراییلیانو ته دا خبرې وکړې، خو هغوی د هغه خبرو ته غوږ ونه نیوه، ځکه چې د هغوی زړونه د بې رحمانه غلامۍ په سبب مات شوي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus6_verse_9.mp3', '', 1761754199, 1761754199),
(51355, 'Exodus 6:10', 'Exodus', 6, 10, 'بیا څښتن موسی ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus6_verse_10.mp3', '', 1761754199, 1761754199),
(51356, 'Exodus 6:11', 'Exodus', 6, 11, '«لاړ شه او د مصر پاچا فرعون ته ووایه چې اسراییلیان پرېږدي چې د مصر څخه ووځي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus6_verse_11.mp3', '', 1761754199, 1761754199),
(51357, 'Exodus 6:12', 'Exodus', 6, 12, 'موسی په ځواب کې وویل: «اسراییلیان چې زما خبره نه اوري، نو فرعون به یې څنګه واوري، ځکه چې زه ښې خبرې نه شم کولای.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus6_verse_12.mp3', '', 1761754199, 1761754199),
(51358, 'Exodus 6:13', 'Exodus', 6, 13, 'څښتن موسی او هارون ته حکم وکړ چې اسراییلیانو او د مصر پاچا ته ووایي: «څښتن مونږ ته حکم کړی دی چې اسراییلیان د مصر څخه راوباسئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus6_verse_13.mp3', '', 1761754199, 1761754199),
(51359, 'Exodus 6:14', 'Exodus', 6, 14, 'روبین د یعقوب مشر زوی څلور زامن درلودل چې حنوک، فلو، حصرون او کرمي نومېدل. هغوی د هغو طایفو نیکونه وو چې د هغوی په نوم یادیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus6_verse_14.mp3', '', 1761754199, 1761754199),
(51360, 'Exodus 6:15', 'Exodus', 6, 15, 'شمعون شپږ زامن درلودل: یموییل، یامین، اوهد، یاکین، صوحر او شاوول چې د یوې کنعانۍ ښځې زوی ؤ. هغوی د هغو طایفو نیکونه وو چې د هغوی په نوم یادیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus6_verse_15.mp3', '', 1761754199, 1761754199),
(51361, 'Exodus 6:16', 'Exodus', 6, 16, 'لاوي درې زامن درلودل چې جرشون، قهات او مراري نومېدل. هغوی د هغو طایفو نیکونه وو چې د هغوی په نوم یادیږي. لاوي یوسلو اووه دېرش کاله ژوند وکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus6_verse_16.mp3', '', 1761754199, 1761754199),
(51362, 'Exodus 6:17', 'Exodus', 6, 17, 'جرشون دوه زامن درلودل چې لبني او شمعي نومېدل چې هغوی د خپلو طایفو نیکونه شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus6_verse_17.mp3', '', 1761754199, 1761754199),
(51363, 'Exodus 6:18', 'Exodus', 6, 18, 'قهات څلور زامن درلودل چې عمرام، یصهار، حبرون او عزییل نومېدل. قهات یوسلو دري دېرش کاله ژوند وکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus6_verse_18.mp3', '', 1761754199, 1761754199),
(51364, 'Exodus 6:19', 'Exodus', 6, 19, 'مراري دوه زامن درلودل چې محلي او موشي نومېدل. دا د لاوي طایفې وې د هغوی د اولادې له مخې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus6_verse_19.mp3', '', 1761754199, 1761754199),
