(51366, 'Exodus 6:21', 'Exodus', 6, 21, 'یصهار درې زامن درلودل چې قورح، نفج او زکري نومېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus6_verse_21.mp3', '', 1761754199, 1761754199),
(51367, 'Exodus 6:22', 'Exodus', 6, 22, 'عزییل هم درې زامن درلودل چې میشاییل، ایلصافان او ستري نومېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus6_verse_22.mp3', '', 1761754199, 1761754199),
(51368, 'Exodus 6:23', 'Exodus', 6, 23, 'هارون د الیشابع سره چې د عمیناداب لور او د نشحون خور وه، واده وکړ او د هغې څخه ناداب، ابیهو، العازار او ایتامار پیدا شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus6_verse_23.mp3', '', 1761754199, 1761754199),
(51369, 'Exodus 6:24', 'Exodus', 6, 24, 'قورح درې زامن درلودل چې اسیر، القانه او ابیاساف نومېدل. دوی د قورح د طایفو نیکونه وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus6_verse_24.mp3', '', 1761754199, 1761754199),
(51370, 'Exodus 6:25', 'Exodus', 6, 25, 'العازار د هارون زوی د فوتي ییل د یوې لور سره واده وکړ او د هغې نه فینحاس پیدا شو. دا طایفه په طایفه د لاوي د کورنیو مشران وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus6_verse_25.mp3', '', 1761754199, 1761754199),
(51371, 'Exodus 6:26', 'Exodus', 6, 26, 'هارون او موسی هماغه خلک وو چې څښتن ورته وویل: «د اسراییلو قبیلې د مصر څخه راوباسئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus6_verse_26.mp3', '', 1761754199, 1761754199),
(51372, 'Exodus 6:27', 'Exodus', 6, 27, 'دا هغه خلک وو چې فرعون سره یې د مصر څخه د اسراییلیانو د ویستلو په هکله خبرې کړې وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus6_verse_27.mp3', '', 1761754199, 1761754199),
(51373, 'Exodus 6:28', 'Exodus', 6, 28, 'کله چې څښتن د موسی سره د مصر په خاوره کې خبرې وکړې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus6_verse_28.mp3', '', 1761754199, 1761754199),
(51374, 'Exodus 6:29', 'Exodus', 6, 29, 'هغه موسی ته وویل: «زه څښتن یم. زه چې هرڅه تاته وایم هغه د مصر پاچا ته ووایه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus6_verse_29.mp3', '', 1761754199, 1761754199),
(51375, 'Exodus 6:30', 'Exodus', 6, 30, 'خو موسی څښتن ته وویل: «دا چې زه ښې خبرې نه شم کولای، نو څنګه به فرعون راته غوږ ونیسي؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus6_verse_30.mp3', '', 1761754199, 1761754199),
